import { ADDRESS_ZERO } from '@uniswap/router-sdk'
import { CurrencyAmount, Token, Currency } from '@uniswap/sdk-core'
import { WRAPPED_NATIVE_CURRENCY } from 'uniswap/src/constants/tokens'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { createCollectFeesStep } from 'uniswap/src/features/transactions/liquidity/steps/collectFees'
import { orderCollectFeesSteps } from 'uniswap/src/features/transactions/liquidity/steps/collectFeesSteps'
import { orderDecreaseLiquiditySteps } from 'uniswap/src/features/transactions/liquidity/steps/decreaseLiquiditySteps'
import { createDecreasePositionStep, createDecreasePositionStepBatched } from 'uniswap/src/features/transactions/liquidity/steps/decreasePosition'
import { orderIncreaseLiquiditySteps } from 'uniswap/src/features/transactions/liquidity/steps/increaseLiquiditySteps'
import {
  createCreatePositionAsyncStep,
  createIncreasePositionAsyncStep,
  createIncreasePositionStep,
  createIncreasePositionStepBatched,
} from 'uniswap/src/features/transactions/liquidity/steps/increasePosition'
import {
  createMigratePositionAsyncStep,
  createMigratePositionStep,
} from 'uniswap/src/features/transactions/liquidity/steps/migrate'
import type { IncreasePositionFallbackStep } from 'uniswap/src/features/transactions/liquidity/steps/increasePosition'
import type { DecreasePositionFallbackStep } from 'uniswap/src/features/transactions/liquidity/steps/decreasePosition'
import { orderMigrateLiquiditySteps } from 'uniswap/src/features/transactions/liquidity/steps/migrationSteps'
import {
  LiquidityTransactionType,
  LiquidityTxAndGasInfo,
  isValidLiquidityTxContext,
} from 'uniswap/src/features/transactions/liquidity/types'
import { createApprovalTransactionStep } from 'uniswap/src/features/transactions/steps/approve'
import { createPermit2SignatureStep } from 'uniswap/src/features/transactions/steps/permit2Signature'
import { createPermit2TransactionStep } from 'uniswap/src/features/transactions/steps/permit2Transaction'
import { createRevocationTransactionStep } from 'uniswap/src/features/transactions/steps/revoke'
import { TransactionStep } from 'uniswap/src/features/transactions/steps/types'
import { ValidatedTransactionRequest } from 'uniswap/src/features/transactions/swap/utils/trade'

// Helper function to safely get wrapped currency for Abstract chains
function getWrappedCurrency(currency: Currency): Token {
  if (currency.isToken) {
    return currency as Token
  }
  
  // For native currencies, use our WRAPPED_NATIVE_CURRENCY mapping for Abstract chains
  const wrappedToken = WRAPPED_NATIVE_CURRENCY[currency.chainId as UniverseChainId]
  if (wrappedToken) {
    return wrappedToken
  }
  
  // Fallback to SDK's wrapped property for non-Abstract chains
  return currency.wrapped
}

// Helper to determine if batching should be used
function shouldUseBatching(
  txContext: LiquidityTxAndGasInfo,
  supportsEip5792: boolean | undefined
): boolean {
  if (!supportsEip5792) {
    return false
  }

  // For increase/create liquidity
  if (txContext.type === 'create' || txContext.type === 'increase') {
    // Only batch if we have approval requests (indicating approval is needed)
    const hasApprovals = Boolean(txContext.approveToken0Request || txContext.approveToken1Request)
    
    // Don't batch for permit/async flows
    const isAsyncFlow = Boolean(txContext.unsigned)
    
    return hasApprovals && !isAsyncFlow
  }

  // For decrease liquidity
  if (txContext.type === 'decrease') {
    // Only batch if we have position token approval (LP token approval)
    const hasPositionApproval = Boolean(txContext.approvePositionTokenRequest)
    
    return hasPositionApproval
  }

  return false
}

export function generateLPTransactionSteps(
  txContext: LiquidityTxAndGasInfo,
  options?: { supportsEip5792?: boolean }
): TransactionStep[] {
  const isValidLP = isValidLiquidityTxContext(txContext)

  if (isValidLP) {
    if (txContext.type === LiquidityTransactionType.Collect) {
      return orderCollectFeesSteps({
        collectFees: createCollectFeesStep(txContext.txRequest),
      })
    }

    const {
      action,
      approveToken0Request,
      approveToken1Request,
      approvePositionTokenRequest,
      token0PermitTransaction,
      token1PermitTransaction,
    } = txContext

    const revokeToken0 = createRevocationTransactionStep(
      txContext.revokeToken0Request,
      getWrappedCurrency(action.currency0Amount.currency),
    )
    const revokeToken1 = createRevocationTransactionStep(
      txContext.revokeToken1Request,
      getWrappedCurrency(action.currency1Amount.currency),
    )
    const approvalToken0 = createApprovalTransactionStep(approveToken0Request, action.currency0Amount)
    const approvalToken1 = createApprovalTransactionStep(approveToken1Request, action.currency1Amount)
    const approvalPositionToken = createApprovalTransactionStep(
      approvePositionTokenRequest,
      action.liquidityToken ? CurrencyAmount.fromRawAmount(action.liquidityToken, 1) : undefined,
      [action.currency0Amount.currency, action.currency1Amount.currency],
    )

    const token0PermitTransactionStep = createPermit2TransactionStep(token0PermitTransaction, action.currency0Amount, [
      action.currency0Amount.currency,
      action.currency1Amount.currency,
    ])

    const token1PermitTransactionStep = createPermit2TransactionStep(token1PermitTransaction, action.currency1Amount, [
      action.currency0Amount.currency,
      action.currency1Amount.currency,
    ])

    switch (txContext.type) {
      case 'decrease':
        if (shouldUseBatching(txContext, options?.supportsEip5792)) {
          // Create batched transaction with position token approval and decrease
          const batchedTxRequests: ValidatedTransactionRequest[] = []
          const fallbackSteps: DecreasePositionFallbackStep[] = []
          
          if (approvalPositionToken) {
            batchedTxRequests.push(approvalPositionToken.txRequest)
            fallbackSteps.push(approvalPositionToken)
          }
          
          // Add main transaction
          batchedTxRequests.push(txContext.txRequest)
          fallbackSteps.push(createDecreasePositionStep(txContext.txRequest))
          
          return orderDecreaseLiquiditySteps({
            approvalPositionToken: undefined, // Skip separate approval step - it's batched
            decreasePosition: createDecreasePositionStepBatched(batchedTxRequests, fallbackSteps),
          })
        } else {
          return orderDecreaseLiquiditySteps({
            approvalPositionToken,
            decreasePosition: createDecreasePositionStep(txContext.txRequest),
          })
        }
      case 'migrate':
        if (txContext.unsigned) {
          return orderMigrateLiquiditySteps({
            permit: createPermit2SignatureStep(
              txContext.permit.typedData,
              new Token(1, ADDRESS_ZERO, 1, 'Uniswap V3 Positions NFT-V1', 'Uniswap V3 Positions NFT-V1'),
            ),
            migrate: createMigratePositionAsyncStep(
              txContext.migratePositionRequestArgs,
              txContext.permit.typedData.values.deadline as number,
            ),
          })
        } else {
          return orderMigrateLiquiditySteps({
            permit: undefined,
            migrate: createMigratePositionStep(txContext.txRequest),
          })
        }
      case 'create':
      case 'increase':
        if (txContext.unsigned) {
          return orderIncreaseLiquiditySteps({
            revokeToken0,
            revokeToken1,
            approvalToken0,
            approvalToken1,
            approvalPositionToken,
            permit: createPermit2SignatureStep(txContext.permit.typedData, action.currency0Amount.currency), // TODO: what about for multiple tokens
            token0PermitTransaction: undefined,
            token1PermitTransaction: undefined,
            increasePosition:
              txContext.type === 'increase'
                ? createIncreasePositionAsyncStep(txContext.increasePositionRequestArgs)
                : createCreatePositionAsyncStep(txContext.createPositionRequestArgs),
          })
        } else if (shouldUseBatching(txContext, options?.supportsEip5792)) {
          // Create batched transaction with approvals and main tx
          const approvalTxs: ValidatedTransactionRequest[] = []
          const fallbackSteps: IncreasePositionFallbackStep[] = []
          
          if (approvalToken0) {
            approvalTxs.push(approvalToken0.txRequest)
            fallbackSteps.push(approvalToken0)
          }
          if (approvalToken1) {
            approvalTxs.push(approvalToken1.txRequest)
            fallbackSteps.push(approvalToken1)
          }
          if (approvalPositionToken) {
            approvalTxs.push(approvalPositionToken.txRequest)
            fallbackSteps.push(approvalPositionToken)
          }
          
          // Add main transaction
          approvalTxs.push(txContext.txRequest)
          fallbackSteps.push(createIncreasePositionStep(txContext.txRequest))
          
          return orderIncreaseLiquiditySteps({
            revokeToken0,
            revokeToken1,
            approvalToken0: undefined, // Skip separate approval steps - they're batched
            approvalToken1: undefined,
            approvalPositionToken: undefined,
            permit: undefined,
            token0PermitTransaction: token0PermitTransactionStep,
            token1PermitTransaction: token1PermitTransactionStep,
            increasePosition: createIncreasePositionStepBatched(approvalTxs, fallbackSteps),
          })
        } else {
          return orderIncreaseLiquiditySteps({
            revokeToken0,
            revokeToken1,
            approvalToken0,
            approvalToken1,
            approvalPositionToken,
            permit: undefined,
            token0PermitTransaction: token0PermitTransactionStep,
            token1PermitTransaction: token1PermitTransactionStep,
            increasePosition: createIncreasePositionStep(txContext.txRequest),
          })
        }
    }
  }

  return []
}
