import { useQuery } from '@tanstack/react-query'
import { Token } from '@uniswap/sdk-core'
import { useReadContracts } from 'wagmi'
import { Address } from 'viem'
import { UniverseChainId } from 'uniswap/src/features/chains/types'
import { isAddress } from 'utilities/src/addresses'
import { useMemo } from 'react'
import { CurrencyInfo } from 'uniswap/src/features/dataApi/types'
import { SafetyLevel, ProtectionResult } from 'uniswap/src/data/graphql/uniswap-data-api/__generated__/types-and-hooks'
import { getCurrencySafetyInfo } from 'uniswap/src/features/dataApi/utils'
import { getTokenLogoUrl } from 'uniswap/src/constants/tokenLogos'
import { currencyId } from 'uniswap/src/utils/currencyId'

// Standard ERC20 ABI for token metadata
const ERC20_METADATA_ABI = [
  {
    name: 'name',
    type: 'function',
    stateMutability: 'view',
    inputs: [],
    outputs: [{ name: '', type: 'string' }]
  },
  {
    name: 'symbol',
    type: 'function',
    stateMutability: 'view',
    inputs: [],
    outputs: [{ name: '', type: 'string' }]
  },
  {
    name: 'decimals',
    type: 'function',
    stateMutability: 'view',
    inputs: [],
    outputs: [{ name: '', type: 'uint8' }]
  },
  {
    name: 'totalSupply',
    type: 'function',
    stateMutability: 'view',
    inputs: [],
    outputs: [{ name: '', type: 'uint256' }]
  }
] as const

export interface TokenFromAddressResult {
  data: CurrencyInfo | null
  loading: boolean
  error: string | null
  isValidToken: boolean
}

/**
 * Hook to fetch token metadata from blockchain by contract address
 * Returns CurrencyInfo if valid ERC20 token, null otherwise
 */
export function useTokenFromAddress(
  address: string | null | undefined,
  chainId: UniverseChainId
): TokenFromAddressResult {
  const validAddress = useMemo(() => {
    return address ? isAddress(address) : false
  }, [address])

  // Fetch token metadata using wagmi
  const {
    data: contractData,
    isLoading: contractLoading,
    error: contractError
  } = useReadContracts({
    contracts: validAddress ? [
      {
        address: validAddress as Address,
        abi: ERC20_METADATA_ABI,
        functionName: 'name',
        chainId
      },
      {
        address: validAddress as Address,
        abi: ERC20_METADATA_ABI,
        functionName: 'symbol',
        chainId
      },
      {
        address: validAddress as Address,
        abi: ERC20_METADATA_ABI,
        functionName: 'decimals',
        chainId
      },
      {
        address: validAddress as Address,
        abi: ERC20_METADATA_ABI,
        functionName: 'totalSupply',
        chainId
      }
    ] : undefined,
    query: {
      enabled: !!validAddress,
      staleTime: 1000 * 60 * 60, // 1 hour - token metadata rarely changes
      refetchOnMount: false,
      refetchOnWindowFocus: false,
    }
  })
  

  const result = useMemo((): TokenFromAddressResult => {
    if (!validAddress) {
      return {
        data: null,
        loading: false,
        error: 'Invalid address',
        isValidToken: false
      }
    }

    if (contractLoading) {
      return {
        data: null,
        loading: true,
        error: null,
        isValidToken: false
      }
    }

    if (contractError) {
      return {
        data: null,
        loading: false,
        error: 'Failed to fetch token data',
        isValidToken: false
      }
    }

    if (!contractData || contractData.some(result => result.status === 'failure')) {
      // Check if it's because the address is not a contract
      const isNotContract = contractData?.some(result => 
        result.status === 'failure' && 
        result.error?.message?.includes('address is not a contract')
      )
      
      const errorMessage = isNotContract 
        ? 'Address is not a valid contract'
        : 'Not a valid ERC20 token'
      
      return {
        data: null,
        loading: false,
        error: errorMessage,
        isValidToken: false
      }
    }

    const [nameResult, symbolResult, decimalsResult, totalSupplyResult] = contractData

    if (
      nameResult.status === 'success' &&
      symbolResult.status === 'success' &&
      decimalsResult.status === 'success' &&
      totalSupplyResult.status === 'success'
    ) {
      const name = nameResult.result as string
      const symbol = symbolResult.result as string
      const decimals = decimalsResult.result as number
      const totalSupply = totalSupplyResult.result as bigint

      // Validate that we got reasonable token metadata
      if (!name || !symbol || decimals > 18 || decimals < 0) {
        return {
          data: null,
          loading: false,
          error: 'Invalid token metadata',
          isValidToken: false
        }
      }

      try {
        // Create Token instance
        const token = new Token(chainId, validAddress, decimals, symbol, name)

        // Create CurrencyInfo with warning safety level for unknown tokens
        const safetyInfo = getCurrencySafetyInfo(SafetyLevel.MediumWarning, {
          attackTypes: [],
          result: ProtectionResult.Unknown,
        })

        const currencyInfo: CurrencyInfo = {
          currencyId: currencyId(token),
          currency: token,
          logoUrl: getTokenLogoUrl(validAddress),
          safetyLevel: SafetyLevel.MediumWarning,
          safetyInfo,
          isSpam: false,
        }

        return {
          data: currencyInfo,
          loading: false,
          error: null,
          isValidToken: true
        }
      } catch (error) {
        return {
          data: null,
          loading: false,
          error: 'Failed to create token',
          isValidToken: false
        }
      }
    }

    return {
      data: null,
      loading: false,
      error: 'Incomplete token data',
      isValidToken: false
    }
  }, [validAddress, contractLoading, contractError, contractData, chainId])

  return result
}