"use strict";
import { useEffect, useState } from "react";
import { useChainId } from "wagmi";
import { useAccount } from "./useAccount";
export function useProviderChainId() {
  const account = useAccount();
  const wagmiChainId = useChainId();
  const [detectedChainId, setDetectedChainId] = useState(wagmiChainId);
  const [isDetecting, setIsDetecting] = useState(true);
  useEffect(() => {
    if (!account.connector || !account.isConnected) {
      setDetectedChainId(wagmiChainId);
      setIsDetecting(false);
      return;
    }
    let cleanup;
    const setupListener = async () => {
      try {
        if (typeof account.connector.getProvider !== "function") {
          console.warn("useProviderChainId: Connector does not support getProvider, using fallback chain detection");
          setDetectedChainId(wagmiChainId);
          setIsDetecting(false);
          return;
        }
        const provider = await account.connector.getProvider();
        const parseChainId = (chainId) => {
          if (!chainId) return void 0;
          if (typeof chainId === "number") {
            console.log("useProviderChainId: Chain ID is number:", chainId);
            return chainId;
          }
          const chainIdStr = String(chainId);
          if (chainIdStr.startsWith("0x")) {
            const parsed2 = parseInt(chainIdStr, 16);
            console.log("useProviderChainId: Parsed hex chain ID:", chainIdStr, "->", parsed2);
            return parsed2;
          }
          const parsed = parseInt(chainIdStr, 10);
          console.log("useProviderChainId: Parsed decimal chain ID:", chainIdStr, "->", parsed);
          return parsed;
        };
        console.log("useProviderChainId: Provider chainId:", provider?.chainId, "Type:", typeof provider?.chainId);
        console.log("useProviderChainId: Connector:", account.connector.name, "Wagmi chainId:", wagmiChainId);
        if (provider?.chainId) {
          const currentChain = parseChainId(provider.chainId);
          if (currentChain) {
            console.log("useProviderChainId: Setting detected chain ID to:", currentChain);
            setDetectedChainId(currentChain);
          } else {
            console.warn("useProviderChainId: Failed to parse chainId, using wagmi fallback");
            setDetectedChainId(wagmiChainId);
          }
          setIsDetecting(false);
        } else {
          console.log("useProviderChainId: No provider chainId, using wagmi chainId:", wagmiChainId);
          setDetectedChainId(wagmiChainId);
          setIsDetecting(false);
        }
        if (provider?.on) {
          const handleChainChanged = (chainIdValue) => {
            const newChainId = parseChainId(chainIdValue);
            if (newChainId) {
              console.log("useProviderChainId: Chain changed to:", newChainId);
              setDetectedChainId(newChainId);
            }
          };
          provider.on("chainChanged", handleChainChanged);
          cleanup = () => {
            provider.removeListener("chainChanged", handleChainChanged);
          };
        }
      } catch (error) {
        console.error("useProviderChainId: Error setting up chain listener:", error);
        setDetectedChainId(wagmiChainId);
        setIsDetecting(false);
      }
    };
    setupListener();
    return () => {
      cleanup?.();
    };
  }, [account.connector, account.isConnected, wagmiChainId]);
  return {
    chainId: detectedChainId ?? wagmiChainId,
    isDetecting
  };
}
