// Pool search queries
const V2_POOL_SEARCH_QUERY = `
  query SearchV2Pools($searchText: String!, $first: Int!) {
    pairs(
      first: $first
      orderBy: reserveUSD
      orderDirection: desc
      where: {
        or: [
          { token0_: { symbol_contains_nocase: $searchText } }
          { token0_: { name_contains_nocase: $searchText } }
          { token1_: { symbol_contains_nocase: $searchText } }
          { token1_: { name_contains_nocase: $searchText } }
        ]
      }
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      reserveUSD
      stable
    }
  }
`

const V3_POOL_SEARCH_QUERY = `
  query SearchV3Pools($searchText: String!, $first: Int!) {
    pools(
      first: $first
      orderBy: totalValueLockedUSD
      orderDirection: desc
      where: {
        or: [
          { token0_: { symbol_contains_nocase: $searchText } }
          { token0_: { name_contains_nocase: $searchText } }
          { token1_: { symbol_contains_nocase: $searchText } }
          { token1_: { name_contains_nocase: $searchText } }
        ]
      }
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      tickSpacing
      totalValueLockedUSD
    }
  }
`

// Gauge cache for on-chain data (pool -> gauge mapping)
let gaugeCache: Map<string, string> | null = null
let gaugeCacheTimestamp = 0
const GAUGE_CACHE_TTL = 5 * 60 * 1000 // 5 minutes

/**
 * Fetch gauges from on-chain Voter contract
 */
async function fetchGaugesOnChain(chainId: UniverseChainId): Promise<Map<string, string>> {
  // Check cache
  const now = Date.now()
  if (gaugeCache && now - gaugeCacheTimestamp < GAUGE_CACHE_TTL) {
    return gaugeCache
  }

  const voterAddress = getContractAddress(chainId, 'Voter')
  const voterAbi = getContractAbi(chainId, 'Voter')

  if (!voterAddress || !voterAbi) {
    return new Map()
  }

  try {
    // Create a public client for on-chain reads
    const client = createPublicClient({
      chain: abstract,
      transport: http('https://api.mainnet.abs.xyz'),
    })

    // Get gauge count
    const lengthResult = await client.readContract({
      address: voterAddress as Address,
      abi: voterAbi,
      functionName: 'length',
      args: [],
    })
    const gaugeCount = Number(lengthResult)

    if (gaugeCount === 0) return new Map()

    // Get all pool addresses in batches
    const poolCalls = Array.from({ length: gaugeCount }, (_, i) => ({
      address: voterAddress as Address,
      abi: voterAbi,
      functionName: 'pools' as const,
      args: [BigInt(i)] as const,
    }))

    const poolsResults = await client.multicall({
      contracts: poolCalls,
      allowFailure: true,
    })

    const poolAddresses = poolsResults
      .filter((r) => r.status === 'success')
      .map((r) => (r.result as string).toLowerCase())

    // Get gauge addresses for each pool
    const gaugeCalls = poolAddresses.map((poolAddr) => ({
      address: voterAddress as Address,
      abi: voterAbi,
      functionName: 'gauges' as const,
      args: [poolAddr as Address] as const,
    }))

    const gaugesResults = await client.multicall({
      contracts: gaugeCalls,
      allowFailure: true,
    })

    // Build pool -> gauge map
    const gaugesMap = new Map<string, string>()
    gaugesResults.forEach((result, i) => {
      if (result.status === 'success') {
        const poolAddr = poolAddresses[i]
        const gaugeAddr = (result.result as string).toLowerCase()
        gaugesMap.set(poolAddr, gaugeAddr)
      }
    })

    // Update cache
    gaugeCache = gaugesMap
    gaugeCacheTimestamp = now

    return gaugesMap
  } catch (error) {
    console.error('[searchPools] Failed to fetch gauges on-chain:', error)
    return gaugeCache || new Map()
  }
}

interface V2PoolSearchResult {
  id: string
  token0: {
    id: string
    symbol: string
    decimals: string
    name: string
  }
  token1: {
    id: string
    symbol: string
    decimals: string
    name: string
  }
  reserveUSD: string
  stable?: boolean
}

interface V3PoolSearchResult {
  id: string
  token0: {
    id: string
    symbol: string
    decimals: string
    name: string
  }
  token1: {
    id: string
    symbol: string
    decimals: string
    name: string
  }
  tickSpacing: string
  totalValueLockedUSD: string
}

// Mapping from tick spacing to fee tier
const TICK_SPACING_TO_FEE = {
  1: 100,
  50: 500,
  100: 500,
  200: 3000,
  2000: 10000,
} as const

async function searchPools(searchText: string, limit: number = 10, chainId: UniverseChainId = UniverseChainId.Mainnet): Promise<{
  v2Pools: V2PoolSearchResult[]
  v3Pools: V3PoolSearchResult[]
  gauges: Map<string, string>
}> {
  try {
    const subgraphs = getAbstractSubgraphs(chainId)

    const v2Subgraph = subgraphs.v2
    const v3Subgraph = subgraphs.v3

    // Fetch V2/V3 pools from subgraphs and gauges from on-chain in parallel
    const [v2Data, v3Data, gaugesMap] = await Promise.all([
      safeFetchSubgraph<{ pairs: V2PoolSearchResult[] }>(
        v2Subgraph,
        {
          query: V2_POOL_SEARCH_QUERY,
          variables: { searchText, first: Math.ceil(limit * 0.6) },
          requestId: 'searchPools.v2',
        },
        'v2 search',
      ),
      safeFetchSubgraph<{ pools: V3PoolSearchResult[] }>(
        v3Subgraph,
        {
          query: V3_POOL_SEARCH_QUERY,
          variables: { searchText, first: Math.ceil(limit * 0.4) },
          requestId: 'searchPools.v3',
        },
        'v3 search',
      ),
      // Fetch gauges from on-chain instead of subgraph
      fetchGaugesOnChain(chainId),
    ])

    return {
      v2Pools: v2Data?.pairs || [],
      v3Pools: v3Data?.pools || [],
      gauges: gaugesMap,
    }
  } catch (error) {
    console.error('Failed to search pools:', error)
    return { v2Pools: [], v3Pools: [], gauges: new Map() }
  }
}

function createCurrencyInfo(tokenData: {
  id: string
  symbol: string
  decimals: string
  name: string
}, chainId: UniverseChainId): CurrencyInfo {
  // Use the actual chainId for proper logo resolution
  const token = new Token(
    chainId,
    tokenData.id,
    parseInt(tokenData.decimals),
    tokenData.symbol,
    tokenData.name
  )

  return {
    currency: token,
    currencyId: `${chainId}-${tokenData.id.toLowerCase()}`,
    logoUrl: getTokenLogoUrl(tokenData.id),
  }
}

function transformV2PoolToOption(pool: V2PoolSearchResult, chainId: UniverseChainId, gaugeAddress?: string): PoolOption {
  return {
    type: OnchainItemListOptionType.Pool,
    poolId: pool.id,
    chainId,
    token0CurrencyInfo: createCurrencyInfo(pool.token0, chainId),
    token1CurrencyInfo: createCurrencyInfo(pool.token1, chainId),
    protocolVersion: ProtocolVersion.V2,
    feeTier: pool.stable ? 500 : 3000, // V2: stable 0.05%, volatile 0.3%
    gaugeAddress,
  }
}

function transformV3PoolToOption(pool: V3PoolSearchResult, chainId: UniverseChainId, gaugeAddress?: string): PoolOption {
  const tickSpacing = parseInt(pool.tickSpacing)
  const feeTier = TICK_SPACING_TO_FEE[tickSpacing as keyof typeof TICK_SPACING_TO_FEE] || 3000

  return {
    type: OnchainItemListOptionType.Pool,
    poolId: pool.id,
    chainId,
    token0CurrencyInfo: createCurrencyInfo(pool.token0, chainId),
    token1CurrencyInfo: createCurrencyInfo(pool.token1, chainId),
    protocolVersion: ProtocolVersion.V3,
    feeTier,
    gaugeAddress,
  }
}

export function usePoolSearchResults(
  searchQuery: string | null,
  chainFilter: UniverseChainId | null = null,
  limit: number = 10
): {
  data: PoolOption[]
  loading: boolean
  error: any
} {
  // Default to mainnet instead of testnet when no chain filter is provided
  const chainId = chainFilter || UniverseChainId.Mainnet
  const trimmedQuery = searchQuery?.trim()
  
  const {
    data: poolsData,
    isLoading,
    error,
  } = useQuery({
    queryKey: ['pool-search', trimmedQuery, chainId, limit],
    queryFn: () => searchPools(trimmedQuery!, limit, chainId),
    enabled: Boolean(trimmedQuery && trimmedQuery.length >= 2), // Only search with 2+ characters
    staleTime: 30 * 1000, // 30 seconds
  })

  const poolOptions = useMemo(() => {
    if (!poolsData) return []

    const allPools: PoolOption[] = []

    // Transform V2 pools
    poolsData.v2Pools.forEach((pool) => {
      const gaugeAddress = poolsData.gauges.get(pool.id.toLowerCase())
      allPools.push(transformV2PoolToOption(pool, chainId, gaugeAddress))
    })

    // Transform V3 pools
    poolsData.v3Pools.forEach((pool) => {
      const gaugeAddress = poolsData.gauges.get(pool.id.toLowerCase())
      allPools.push(transformV3PoolToOption(pool, chainId, gaugeAddress))
    })

    return allPools.slice(0, limit)
  }, [poolsData, chainId, limit])

  return {
    data: poolOptions,
    loading: isLoading,
    error,
  }
}
async function safeFetchSubgraph<T>(
  endpoint: AbstractSubgraphEndpoint,
  options: { query: string; variables?: Record<string, unknown>; requestId: string },
  label: string,
): Promise<T | null> {
  try {
    return await fetchFromSubgraph<T>(endpoint, options)
  } catch (error) {
    console.error(`[searchPools] ${label} failed:`, error)
    return null
  }
}
