async function executeMulticall(provider, calls, chunkSize = 256) {
  if (calls.length === 0) {
    return { blockNumber: BigNumber.from(0), results: [] };
  }
  const contract = getMulticallContract(provider);
  const aggregated = [];
  let lastBlock = BigNumber.from(0);
  for (let i = 0; i < calls.length; i += chunkSize) {
    const chunk = calls.slice(i, i + chunkSize);
    const [blockNumber, returnData] = await contract.callStatic.aggregate(chunk);
    lastBlock = blockNumber;
    aggregated.push(...returnData);
  }
  return { blockNumber: lastBlock, results: aggregated };
}
