async function fetchAllPoolsFromFactory({
  provider,
  factoryAddress,
  abi,
  chunkSize = 256
}) {
  if (!factoryAddress) {
    return [];
  }
  const factoryContract = new Contract(factoryAddress, abi, provider);
  let poolCount = 0;
  try {
    const length = await factoryContract.allPoolsLength();
    poolCount = length.toNumber();
  } catch (error) {
    console.warn("[onChainPositions] Failed to read allPoolsLength", { factoryAddress, error });
    return [];
  }
  if (poolCount === 0) {
    return [];
  }
  const factoryInterface = new Interface(abi);
  const calls = [];
  for (let i = 0; i < poolCount; i++) {
    calls.push({
      target: factoryAddress,
      callData: factoryInterface.encodeFunctionData("allPools", [i])
    });
  }
  try {
    const { results } = await executeMulticall(provider, calls, chunkSize);
    return results.map((returnData) => {
      try {
        const [poolAddress] = factoryInterface.decodeFunctionResult("allPools", returnData);
        return poolAddress;
      } catch {
        return void 0;
      }
    }).filter((poolAddress) => Boolean(poolAddress));
  } catch (error) {
    console.warn("[onChainPositions] Failed to enumerate pools for factory", { factoryAddress, error });
    return [];
  }
}
