// Extended Token class with whitelisted and feeOnTransfer attributes
export class WhitelistedToken extends Token {
  public readonly whitelisted: boolean
  public readonly feeOnTransfer: boolean

  constructor(
    chainId: number,
    address: string,
    decimals: number,
    symbol: string,
    name: string,
    whitelisted: boolean = false,
    feeOnTransfer: boolean = false
  ) {
    super(chainId, address, decimals, symbol, name)
    this.whitelisted = whitelisted
    this.feeOnTransfer = feeOnTransfer
  }
}

