// Helper function to get tokens
export function getToken(chainId: UniverseChainId): {
  usdc: Token
  usdt?: Token
  dai?: Token
  weth: Token
  abx: Token
} {
  switch (chainId) {
    case UniverseChainId.Mainnet:
      return {
        usdc: USDC_ABSTRACT_MAINNET,
        usdt: USDT_ABSTRACT_MAINNET,
        dai: DAI_ABSTRACT_MAINNET,
        weth: WETH_ABSTRACT_MAINNET,
        abx: ABX_ABSTRACT_MAINNET,
      }
    case UniverseChainId.Sepolia:
      return {
        usdc: USDC_ABSTRACT_TESTNET,
        usdt: USDT_ABSTRACT_TESTNET,
        dai: DAI_ABSTRACT_TESTNET,
        weth: WETH_ABSTRACT_TESTNET,
        abx: ABX_ABSTRACT_TESTNET,
      }
    default:
      throw new Error(`Unsupported chain ID: ${chainId}`)
  }
}

// Helper function to get the official DEX token list
// These tokens appear in token selectors, liquidity pool tables, etc.
export function getDexTokenList(chainId: UniverseChainId): WhitelistedToken[] {
  if (chainId === UniverseChainId.Mainnet) {
    // Mainnet token list: ETH, WETH, USDC.e, USDT, PENGU, ABX, Kona ABX, KONA, YGG, NOOT, ABSTER, BIG, GOONER, Polly, GUGO, UWU69, RETSBA, GOD, CYCLOPS, GRIND, ALFA, BEAVER, SMP, DREAM, CLU, ERK
    return [
      WETH_ABSTRACT_MAINNET,
      USDC_ABSTRACT_MAINNET, // USDC.e
      USDT_ABSTRACT_MAINNET,
      PENGU_ABSTRACT_MAINNET,
      ABX_ABSTRACT_MAINNET,
      KABX_ABSTRACT_MAINNET,
      KONA_ABSTRACT_MAINNET,
      YGG_ABSTRACT_MAINNET,
      NOOT_ABSTRACT_MAINNET,
      ABSTER_ABSTRACT_MAINNET,
      BIG_ABSTRACT_MAINNET,
      GOONER_ABSTRACT_MAINNET,
      ZOOME_ABSTRACT_MAINNET,
      GSCORE_ABSTRACT_MAINNET,
      GBLUE_ABSTRACT_MAINNET,
      FBOMB_ABSTRACT_MAINNET,
      GTBTC_ABSTRACT_MAINNET,
      GUSD_ABSTRACT_MAINNET,
      CHECK_ABSTRACT_MAINNET,
      BORNE_ABSTRACT_MAINNET,
      POLLY_ABSTRACT_MAINNET,
      GUGO_ABSTRACT_MAINNET,
      UWU69_ABSTRACT_MAINNET,
      RETSBA_ABSTRACT_MAINNET,
      GOD_ABSTRACT_MAINNET,
      CYCLOPS_ABSTRACT_MAINNET,
      GRIND_ABSTRACT_MAINNET,
      ALFA_ABSTRACT_MAINNET,
      BEAVER_ABSTRACT_MAINNET,
      SMP_ABSTRACT_MAINNET,
      DREAM_ABSTRACT_MAINNET,
      CLU_ABSTRACT_MAINNET,
      ERK_ABSTRACT_MAINNET,
    ]
  }

  // Testnet and other chains
  const tokens = getToken(chainId)
  const allTokens = [tokens.usdc, tokens.weth, tokens.abx]

  // Add optional tokens if they exist
  if (tokens.usdt) allTokens.push(tokens.usdt)
  if (tokens.dai) allTokens.push(tokens.dai)

  return allTokens.filter((token): token is WhitelistedToken => token instanceof WhitelistedToken)
}

// Helper function to check if a token is whitelisted for gauge incentives
export function isTokenWhitelistedForIncentives(token: Token | WhitelistedToken | Currency): boolean {
  // Whitelist addresses array
  const whitelistedAddresses = [
    ABX_ABSTRACT_TESTNET.address.toLowerCase(),
    ABX_ABSTRACT_MAINNET.address.toLowerCase(),
    USDC_ABSTRACT_TESTNET.address.toLowerCase(),
    USDC_ABSTRACT_MAINNET.address.toLowerCase(),
    WETH_ABSTRACT_MAINNET.address.toLowerCase(),
    USDT_ABSTRACT_MAINNET.address.toLowerCase(),
    PENGU_ABSTRACT_MAINNET.address.toLowerCase(),
    KABX_ABSTRACT_MAINNET.address.toLowerCase(),
    KONA_ABSTRACT_MAINNET.address.toLowerCase(),
    YGG_ABSTRACT_MAINNET.address.toLowerCase(),
    ABSTER_ABSTRACT_MAINNET.address.toLowerCase(),
    BIG_ABSTRACT_MAINNET.address.toLowerCase(),
    GOONER_ABSTRACT_MAINNET.address.toLowerCase(),
    POLLY_ABSTRACT_MAINNET.address.toLowerCase(),
    GUGO_ABSTRACT_MAINNET.address.toLowerCase(),
    RETSBA_ABSTRACT_MAINNET.address.toLowerCase(),
    GOD_ABSTRACT_MAINNET.address.toLowerCase(),
    CYCLOPS_ABSTRACT_MAINNET.address.toLowerCase(),
    BEAVER_ABSTRACT_MAINNET.address.toLowerCase(),
  ]

  // For native currencies (ETH), check the wrapped version (WETH)
  if (token.isNative) {
    const wrappedToken = WRAPPED_NATIVE_CURRENCY[token.chainId as UniverseChainId]
    if (wrappedToken instanceof WhitelistedToken) {
      return wrappedToken.whitelisted
    }
    return whitelistedAddresses.includes(wrappedToken.address.toLowerCase())
  }

  // Token must have an address property
  if (!('address' in token) || !token.address) {
    return false
  }

  // First check if it's a WhitelistedToken instance
  if (token instanceof WhitelistedToken) {
    return token.whitelisted
  }

  // Fallback: check by address for our known whitelisted tokens
  return whitelistedAddresses.includes(token.address.toLowerCase())
}

// Helper function to get tokens whitelisted for gauge incentives (subset of DEX token list)
export function getWhitelistedTokens(chainId: UniverseChainId): WhitelistedToken[] {
  return getDexTokenList(chainId).filter(token => token.whitelisted)
}

// Array of fee-on-transfer token addresses (lowercase)
// Add new fee-on-transfer tokens here as they are added to the DEX
const FEE_ON_TRANSFER_TOKEN_ADDRESSES: string[] = [
  FBOMB_ABSTRACT_MAINNET.address.toLowerCase(),
]

// Helper function to check if a token has fee-on-transfer (tax on transfers)
// Fee-on-transfer tokens require special router functions for swaps
export function isTokenFeeOnTransfer(token: Token | WhitelistedToken | Currency | null | undefined): boolean {
  if (!token) {
    return false
  }

  // Native currencies (ETH) don't have fee-on-transfer
  if (token.isNative) {
    return false
  }

  // Token must have an address property
  if (!('address' in token) || !token.address) {
    return false
  }

  // First check if it's a WhitelistedToken instance with the feeOnTransfer property
  if (token instanceof WhitelistedToken) {
    return token.feeOnTransfer
  }

  // Fallback: check by address for our known fee-on-transfer tokens
  return FEE_ON_TRANSFER_TOKEN_ADDRESSES.includes(token.address.toLowerCase())
}

// Helper function to get all fee-on-transfer tokens for a chain
export function getFeeOnTransferTokens(chainId: UniverseChainId): WhitelistedToken[] {
  return getDexTokenList(chainId).filter(token => token.feeOnTransfer)
}

