export class ExtendedEther extends NativeCurrency {
  public get wrapped(): Token {
    const chainId = this.chainId as UniverseChainId
    return WRAPPED_NATIVE_CURRENCY[chainId]
  }

  protected constructor(chainId: number) {
    super(chainId, 18, 'ETH', 'Ethereum')
  }

  private static _cachedExtendedEthers: { [chainId: number]: ExtendedEther } = {}

  public static onChain(chainId: number): ExtendedEther {
    return (
      this._cachedExtendedEthers[chainId] ??
      (this._cachedExtendedEthers[chainId] = new ExtendedEther(chainId))
    )
  }
}

// Export function to get native currency name
